    for line in f:
        if line.startswith(">"): continue
        seq += line.strip()

comp = str.maketrans("ACGT","TGCA")
def revcomp(s): return s.translate(comp)[::-1]

table = {}
bases="TCAG"
aas="FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
i=0
for a in bases:
    for b in bases:
        for c in bases:
            table[a+b+c]=aas[i]; i+=1

def translate(s):
    return "".join(table[s[i:i+3]] for i in range(0,len(s)-2,3))

strands = {"+":seq, "-":revcomp(seq)}
orfs=[]
for name,s in strands.items():
    for frame in range(3):
        t = translate(s[frame:])
        # find ORFs from ATG to stop
        # scan
        i=0
