seq = ""
with open("region.fasta") as f:
    for line in f:
        if line.startswith(">"): continue
        seq += line.strip()

# Find repeated substrings of length >= 20 (non-overlapping occurrences count)
from collections import defaultdict
def find_repeats(s, k, mincount=2):
    d = defaultdict(list)
    for i in range(len(s)-k+1):
        d[s[i:i+k]].append(i)
    reps = {km:v for km,v in d.items() if len(v)>=mincount}
    return reps

for k in [20,25,30,40]:
    reps = find_repeats(seq,k)
    print("k=",k,"num repeated kmers:", len(reps))
    # show a few
    for km,v in list(reps.items())[:10]:
        print("   ", km, v)
